INSERT INTO public.quiz_questions (topic_id, question, options, correct_answer, rationale, difficulty)
VALUES
('fundamentals', 'Which action by the nurse represents the most effective method to break the chain of infection in a clinical setting?', '["Wearing clean gloves for all patient contact","Performing hand hygiene before and after patient contact","Recapping needles immediately after use","Administering prophylactic antibiotics"]'::jsonb, 'Performing hand hygiene before and after patient contact', 'Hand hygiene is universally recognized as the single most effective intervention to prevent healthcare-associated infections.', 'easy'),
('fundamentals', 'When assessing a patient for suspected hypocalcemia, which clinical sign demonstrates Trousseau sign?', '["Facial twitching upon tapping the facial nerve","Carpal spasm induced by inflating a blood pressure cuff","Involuntary dorsiflexion of the big toe","Numbness around the perioral area"]'::jsonb, 'Carpal spasm induced by inflating a blood pressure cuff', 'Trousseau sign is carpopedal spasm induced by inflating a blood pressure cuff above systolic pressure for 3 minutes, indicating hypocalcemia. Chvostek sign is facial twitching.', 'medium'),
('fundamentals', 'A nurse is preparing to transfer a non-weight-bearing patient from bed to chair. Which ergonomic principle should the nurse apply?', '["Bend at the waist while keeping knees straight","Keep feet together to narrow the base of support","Bend at the knees and pivot using the feet","Hold the weight as far from the body as possible"]'::jsonb, 'Bend at the knees and pivot using the feet', 'Proper body mechanics involve bending at the knees, maintaining a wide base of support, keeping the load close to the body, and pivoting without twisting.', 'easy'),
('fundamentals', 'Which personal protective equipment (PPE) sequence should the nurse follow when donning PPE for airborne precautions?', '["Gown, Mask/N95 respirator, Goggles, Gloves","Gloves, Goggles, Gown, N95 respirator","N95 respirator, Gown, Gloves, Goggles","Goggles, Gloves, Gown, Mask"]'::jsonb, 'Gown, Mask/N95 respirator, Goggles, Gloves', 'Proper donning order is Gown first, followed by Mask/Respirator, Goggles/Face Shield, and Gloves last.', 'medium'),
('fundamentals', 'A nurse delegates vital signs measurements to an Unlicensed Assistive Personnel (UAP). Which task remains the non-delegable responsibility of the Registered Nurse?', '["Measuring manual blood pressure","Recording pulse oximetry readings","Interpreting vital sign trends and abnormal values","Counting respiratory rate"]'::jsonb, 'Interpreting vital sign trends and abnormal values', 'Assessment, clinical judgment, interpretation, evaluation, and patient teaching cannot be delegated to UAPs.', 'easy'),
('fundamentals', 'A patient with a Stage 2 pressure injury on the sacrum requires wound dressing. Which dressing type is most appropriate for a clean Stage 2 injury with minimal exudate?', '["Dry sterile gauze","Hydrocolloid dressing","Alginate dressing","Wet-to-dry gauze packing"]'::jsonb, 'Hydrocolloid dressing', 'Hydrocolloid dressings support moist wound healing and protect Stage 2 pressure injuries from friction and contamination.', 'medium'),
('fundamentals', 'When administering an intramuscular (IM) injection into the ventrogluteal site of an adult, which anatomical landmarks should the nurse locate?', '["Acromion process and axillary line","Greater trochanter, anterior superior iliac spine, and iliac crest","Vastous lateralis and patella","Posterior superior iliac spine and sacrum"]'::jsonb, 'Greater trochanter, anterior superior iliac spine, and iliac crest', 'The ventrogluteal site is identified by placing the palm on the greater trochanter, index finger on the anterior superior iliac spine, and middle finger along the iliac crest.', 'medium'),
('fundamentals', 'A patient is scheduled for an invasive surgical procedure. Who holds primary legal responsibility for obtaining informed consent?', '["The registered nurse","The healthcare provider performing the procedure","The hospital risk management officer","The surgical scrub technician"]'::jsonb, 'The healthcare provider performing the procedure', 'The provider performing the procedure is legally responsible for explaining risks, benefits, alternatives, and obtaining consent. The nurse witnesses the signature.', 'easy'),
('fundamentals', 'Which action should the nurse perform FIRST when discovering a fire in a patient room?', '["Activate the fire alarm","Extinguish the fire with a C-type extinguisher","Rescue and evacuate the patient from immediate danger","Close all room doors"]'::jsonb, 'Rescue and evacuate the patient from immediate danger', 'Following the RACE acronym: Rescue/Evacuate patients in immediate danger first, Alarm, Contain fire, Extinguish.', 'easy'),
('fundamentals', 'Which pulse site is recommended for assessing circulation to the foot in a peripheral vascular assessment?', '["Popliteal pulse","Posterior tibial and dorsalis pedis pulses","Femoral pulse","Brachial pulse"]'::jsonb, 'Posterior tibial and dorsalis pedis pulses', 'Dorsalis pedis (top of foot) and posterior tibial (behind inner ankle) pulses evaluate distal lower extremity arterial perfusion.', 'easy'),
('fundamentals', 'A nurse assesses a patient receiving enteral tube feedings who suddenly develops dyspnea and coughing. What is the nurse''s PRIORITY action?', '["Check gastric residual volume","Stop the enteral feeding immediately","Notify the healthcare provider","Position the patient prone"]'::jsonb, 'Stop the enteral feeding immediately', 'Dyspnea and coughing during enteral feeding suggest aspiration. Stopping the infusion immediately prevents further pulmonary contamination.', 'hard'),
('fundamentals', 'Which needle gauge and length are standard for an adult subcutaneous insulin injection?', '["18 gauge, 1.5 inch","25 to 31 gauge, 5/16 to 1/2 inch","20 gauge, 1 inch","14 gauge, 2 inch"]'::jsonb, '25 to 31 gauge, 5/16 to 1/2 inch', 'Subcutaneous insulin injections use fine gauge short needles (25-31G, 5/16"-1/2") to deposit medication into subcutaneous tissue without entering muscle.', 'easy'),
('fundamentals', 'When performing tracheostomy suctioning, what is the maximum duration for a single suction pass?', '["5 seconds","10 to 15 seconds","30 seconds","45 seconds"]'::jsonb, '10 to 15 seconds', 'Suctioning should be limited to 10-15 seconds per pass to prevent hypoxia and vagal stimulation.', 'medium'),
('fundamentals', 'Which type of isolation precaution is required for a patient diagnosed with active Pulmonary Tuberculosis?', '["Contact Precautions","Droplet Precautions","Airborne Precautions with N95 mask in a negative-pressure room","Standard Precautions only"]'::jsonb, 'Airborne Precautions with N95 mask in a negative-pressure room', 'Tuberculosis is transmitted via small airborne droplet nuclei requiring airborne isolation, negative airflow pressure room, and fitted N95 respirators.', 'medium'),
('fundamentals', 'What is the minimum recommended duration for handwashing with soap and water according to CDC guidelines?', '["5 seconds","10 seconds","20 seconds","60 seconds"]'::jsonb, '20 seconds', 'The CDC recommends scrubbing hands thoroughly with soap and water for at least 20 seconds.', 'easy'),
('pharmacology', 'A nurse is preparing to administer Digoxin to an adult patient. Which assessment is essential prior to administration?', '["Check respiratory rate for 1 full minute","Assess apical pulse for 1 full minute","Measure blood glucose level","Check deep tendon reflexes"]'::jsonb, 'Assess apical pulse for 1 full minute', 'Digoxin is a cardiac glycoside that slows heart rate. Apical pulse must be assessed for 1 full minute; hold medication if HR is below 60 bpm.', 'medium'),
('pharmacology', 'Which antidote should the nurse have readily available for a patient receiving continuous IV Heparin infusion?', '["Vitamin K","Protamine sulfate","Naloxone","Calcium gluconate"]'::jsonb, 'Protamine sulfate', 'Protamine sulfate is the specific reversal agent for Heparin toxicity. Vitamin K reverses Warfarin.', 'easy'),
('pharmacology', 'A patient taking Lisinopril develops a persistent, dry, non-productive cough. What causes this side effect?', '["Accumulation of bradykinin in the respiratory tract","Fluid overload in pulmonary capillaries","Bronchospasm from histamine release","Bacterial colonization"]'::jsonb, 'Accumulation of bradykinin in the respiratory tract', 'ACE inhibitors (like lisinopril) prevent the breakdown of bradykinin, leading to respiratory accumulation and dry cough in up to 20% of patients.', 'medium'),
('pharmacology', 'Which lab value must be monitored closely for a patient taking Warfarin (Coumadin)?', '["aPTT (activated partial thromboplastin time)","INR (International Normalized Ratio)","Platelet count","Serum Creatinine"]'::jsonb, 'INR (International Normalized Ratio)', 'Warfarin therapy monitoring requires checking PT/INR (therapeutic target typically 2.0 - 3.0). aPTT monitors Heparin.', 'easy'),
('pharmacology', 'A patient is prescribed Levothyroxine for hypothyroidism. What instruction should the nurse provide regarding administration?', '["Take with meals to minimize stomach upset","Take on an empty stomach in the morning with a full glass of water","Take immediately before bedtime","Take with an antacid to enhance absorption"]'::jsonb, 'Take on an empty stomach in the morning with a full glass of water', 'Levothyroxine is best absorbed on an empty stomach at least 30-60 minutes before breakfast.', 'medium'),
('pharmacology', 'Which medication class carries a Black Box Warning for increased risk of tendon rupture, particularly the Achilles tendon?', '["Penicillins","Fluoroquinolones (e.g., Ciprofloxacin)","Macrolides (e.g., Azithromycin)","Cephalosporins"]'::jsonb, 'Fluoroquinolones (e.g., Ciprofloxacin)', 'Fluoroquinolones carry a black box warning for tendinitis and tendon rupture, especially in elderly patients and those taking corticosteroids.', 'hard'),
('pharmacology', 'What is the primary therapeutic indication for administering Naloxone (Narcan)?', '["Reversal of benzodiazepine sedation","Reversal of opioid-induced respiratory depression","Treatment of acetaminophen toxicity","Management of alcohol withdrawal"]'::jsonb, 'Reversal of opioid-induced respiratory depression', 'Naloxone is a competitive opioid antagonist used for emergency reversal of opioid overdose.', 'easy'),
('pharmacology', 'A nurse administers Regular insulin subcutaneously at 07:30 AM. At what time is the patient at HIGHEST risk for hypoglycemia?', '["08:00 AM (30 minutes)","09:30 AM to 11:30 AM (2 to 4 hours)","02:00 PM to 04:00 PM (7 hours)","07:30 PM (12 hours)"]'::jsonb, '09:30 AM to 11:30 AM (2 to 4 hours)', 'Short-acting Regular insulin peaks between 2 to 4 hours post-administration, posing maximum risk for hypoglycemia.', 'medium'),
('pharmacology', 'Which adverse effect should the nurse monitor for in a patient receiving Vancomycin IV who develops red flushing of the face and neck?', '["Anaphylactic cardiac arrest","Red Man Syndrome from rapid infusion rate","Stevens-Johnson Syndrome","Serotonin Syndrome"]'::jsonb, 'Red Man Syndrome from rapid infusion rate', 'Red Man Syndrome is a histamine-mediated reaction caused by rapid IV administration of Vancomycin. Slowing the infusion rate resolves the flushing.', 'medium'),
('pharmacology', 'Which electrolyte imbalance increases the risk of Digoxin toxicity?', '["Hyperkalemia","Hypokalemia","Hypercalcemia","Hyponatremia"]'::jsonb, 'Hypokalemia', 'Hypokalemia (<3.5 mEq/L) enhances digoxin binding to Na+/K+ ATPase, increasing risk of fatal arrhythmias.', 'hard'),
('pharmacology', 'A nurse administers Furosemide (Lasix) IV push. Which potential complication can occur if administered too rapidly?', '["Ototoxicity and transient hearing loss","Hepatotoxicity","Hypertension","Hyperkalemia"]'::jsonb, 'Ototoxicity and transient hearing loss', 'Rapid IV push administration of loop diuretics (Furosemide) can cause ototoxicity and tinnitus. Maximum rate is 20 mg/min.', 'hard'),
('pharmacology', 'Which assessment finding indicates that Nitroglycerin sublingual tablets have been effective for angina pectoris?', '["Heart rate increases to 110 bpm","Blood pressure increases","Patient reports relief of chest pain","ST elevation on ECG"]'::jsonb, 'Patient reports relief of chest pain', 'Nitroglycerin causes coronary vasodilation and decreases preload; the therapeutic objective is prompt reduction or relief of anginal pain.', 'easy'),
('pharmacology', 'What is the therapeutic target range for serum Lithium levels in maintenance therapy for bipolar disorder?', '["0.1 to 0.4 mEq/L","0.6 to 1.2 mEq/L","2.0 to 3.5 mEq/L","5.0 to 7.0 mEq/L"]'::jsonb, '0.6 to 1.2 mEq/L', 'Therapeutic serum lithium levels are 0.6 - 1.2 mEq/L. Levels > 1.5 mEq/L indicate lithium toxicity.', 'medium'),
('pharmacology', 'A patient receiving Metoprolol asks why their heart rate is 54 bpm. Which pharmacological effect explains this?', '["Beta-1 adrenergic blockade causing negative chronotropic effect","Alpha-1 receptor stimulation causing vasoconstriction","Calcium channel entry acceleration","Sodium channel inhibition"]'::jsonb, 'Beta-1 adrenergic blockade causing negative chronotropic effect', 'Metoprolol blocks Beta-1 receptors in the heart, lowering heart rate and contractility.', 'medium'),
('pharmacology', 'Which over-the-counter analgesic should be avoided in a patient taking Anticoagulants due to bleeding risk?', '["Acetaminophen","Ibuprofen (NSAID)","Docusate sodium","Loperamide"]'::jsonb, 'Ibuprofen (NSAID)', 'NSAIDs inhibit platelet cyclooxygenase and prolong bleeding time, compounding anticoagulant risks.', 'easy'),
('medsurg', 'A nurse is caring for a patient experiencing Diabetic Ketoacidosis (DKA). Which IV solution is initially administered?', '["5% Dextrose in Water (D5W)","0.9% Normal Saline (0.9% NaCl)","0.45% Normal Saline (0.45% NaCl)","Dextrose 5% in 0.45% Saline"]'::jsonb, '0.9% Normal Saline (0.9% NaCl)', 'Initial DKA therapy requires rapid intravascular volume expansion using isotonic 0.9% Normal Saline before switching to dextrose-containing fluids.', 'hard'),
('medsurg', 'A patient with chronic kidney disease has a potassium level of 6.8 mEq/L and ECG changes. Which order should the nurse execute FIRST?', '["Administer IV Sodium Polystyrene Sulfonate (Kayexalate)","Administer IV Calcium Gluconate","Obtain a 12-lead ECG","Place patient on a low-potassium diet"]'::jsonb, 'Administer IV Calcium Gluconate', 'Calcium gluconate stabilizes cardiac cell membranes to prevent lethal arrhythmias caused by severe hyperkalemia.', 'hard'),
('medsurg', 'A patient post-thyroidectomy reports tingling around the mouth and fingertips. What complication should the nurse evaluate?', '["Thyroid storm","Hypocalcemia due to accidental parathyroid gland removal","Hyperkalemic surge","Recurrent laryngeal nerve paralysis"]'::jsonb, 'Hypocalcemia due to accidental parathyroid gland removal', 'Accidental removal or injury to parathyroid glands during thyroidectomy causes acute hypocalcemia presenting as perioral paresthesia and tetany.', 'medium'),
('medsurg', 'Which position is recommended for a patient presenting with acute decompensated heart failure and pulmonary edema?', '["Trendelenburg position","High-Fowler position with legs dangling","Supine with legs elevated","Left lateral recumbent position"]'::jsonb, 'High-Fowler position with legs dangling', 'High-Fowler position decreases venous return (preload), reduces pulmonary congestion, and facilitates maximum lung expansion.', 'medium'),
('medsurg', 'Which triad of symptoms classically characterizes Cushing Triad in a patient with increased intracranial pressure (ICP)?', '["Tachycardia, Hypotension, Tachypnea","Bradycardia, Irregular respiration (Cheyne-Stokes), Widened pulse pressure (Systolic Hypertension)","Hypothermia, Tachycardia, Vomiting","Papilledema, Seizures, Diarrhea"]'::jsonb, 'Bradycardia, Irregular respiration (Cheyne-Stokes), Widened pulse pressure (Systolic Hypertension)', 'Cushing Triad indicates late stage elevated ICP: Bradycardia, Systolic hypertension with widening pulse pressure, and respiratory irregularity.', 'hard'),
('medsurg', 'A patient post-hip arthroplasty suddenly reports shortness of breath, chest pain, and anxiety. What is the nurse''s FIRST priority action?', '["Administer oral analgesic","Apply high-flow oxygen via non-rebreather mask and elevate head of bed","Encourage coughing and deep breathing","Notify physical therapy"]'::jsonb, 'Apply high-flow oxygen via non-rebreather mask and elevate head of bed', 'Sudden dyspnea post-orthopedic surgery suggests Pulmonary Embolism (PE). Immediate oxygenation and HOB elevation are life-saving interventions.', 'medium'),
('medsurg', 'Which clinical finding distinguishes Nephrotic Syndrome from Acute Glomerulonephritis?', '["Massive proteinuria (>3.5 g/day) and generalized edema (anasarca)","Gross hematuria (cola-colored urine) and hypertension","Glucosuria and polyuria","Elevated alkaline phosphatase"]'::jsonb, 'Massive proteinuria (>3.5 g/day) and generalized edema (anasarca)', 'Nephrotic syndrome is characterized by heavy proteinuria, hypoalbuminemia, hyperlipidemia, and severe generalized edema.', 'hard'),
('medsurg', 'A patient with COPD is receiving supplemental oxygen. Why is oxygen therapy kept at low flow rates (1-2 L/min)?', '["High oxygen flows cause airway dryness","Hypoxic drive maintains respiration in chronic hypercapnia","Excess oxygen causes cardiac output collapse","Oxygen inhibits surfactant production"]'::jsonb, 'Hypoxic drive maintains respiration in chronic hypercapnia', 'Chronic retention of CO2 leads patients with COPD to rely on low arterial PaO2 (hypoxic drive) to stimulate breathing.', 'medium'),
('medsurg', 'Which initial diagnostic test is prioritized to rule out hemorrhagic stroke when a patient presents with acute neurological deficits?', '["Lumbar puncture","Non-contrast CT scan of the head","Carotid duplex ultrasound","Electroencephalogram (EEG)"]'::jsonb, 'Non-contrast CT scan of the head', 'Non-contrast head CT quickly differentiates hemorrhagic stroke from ischemic stroke prior to thrombolytic therapy.', 'easy'),
('medsurg', 'What is the priority nursing intervention for a patient with a chest tube that has accidentally disconnected from the drainage unit?', '["Clamp the chest tube immediately with padded clamps","Submerge the end of the chest tube in 1-2 inches of sterile water","Cover the insertion site with an occlusive petroleum gauze","Strip the chest tube tubing"]'::jsonb, 'Submerge the end of the chest tube in 1-2 inches of sterile water', 'Submerging the tube end in sterile water re-establishes a water seal, preventing atmospheric air from entering pleural space and causing pneumothorax.', 'hard'),
('medsurg', 'Which lab value is most specific for diagnosing acute myocardial infarction (MI)?', '["CK-MB","Troponin I and Troponin T","Myoglobin","BNP (B-type Natriuretic Peptide)"]'::jsonb, 'Troponin I and Troponin T', 'Troponins I and T are highly sensitive and specific cardiac biomarkers elevated following myocardial injury.', 'easy'),
('medsurg', 'A patient with cirrhosis develops Hepatic Encephalopathy. Which medication is administered to reduce serum ammonia levels?', '["Spironolactone","Lactulose","Furosemide","Propranolol"]'::jsonb, 'Lactulose', 'Lactulose traps ammonia in the gut and promotes excretion through loose bowel movements, lowering blood ammonia.', 'medium'),
('medsurg', 'What is the target blood glucose range for a hospitalized critically ill adult patient on IV insulin infusion?', '["70 to 110 mg/dL","140 to 180 mg/dL","200 to 250 mg/dL","< 60 mg/dL"]'::jsonb, '140 to 180 mg/dL', 'Clinical guidelines recommend keeping blood glucose between 140-180 mg/dL for critically ill adults to prevent hypoglycemia.', 'medium'),
('medsurg', 'Which electrolyte disturbance is the primary cause of paralytic ileus post-abdominal surgery?', '["Hypokalemia","Hypercalcemia","Hyponatremia","Hypermagnesemia"]'::jsonb, 'Hypokalemia', 'Low serum potassium impairs smooth muscle contraction in the GI tract, predisposing patients to paralytic ileus.', 'hard'),
('medsurg', 'Which physical assessment finding is characteristic of acute appendicitis?', '["Positive Murphy sign","Rebound tenderness at McBurney point","Positive Trousseau sign","Grey Turner sign"]'::jsonb, 'Rebound tenderness at McBurney point', 'Rebound tenderness at McBurney point (right lower quadrant) is a cardinal sign of peritoneal irritation from acute appendicitis.', 'easy'),
('maternal', 'A nurse calculates an APGAR score for a newborn at 1 minute post-birth: HR 110, strong cry, active motion, pink body with blue extremities, vigorous grimace. What is the APGAR score?', '["7","8","9","10"]'::jsonb, '9', 'Score: HR >100 (2), Cry (2), Motion (2), Acrocyanosis (1), Grimace (2) = 9 points.', 'medium'),
('maternal', 'Which medication is routinely administered to all newborns within 1-2 hours of birth to prevent hemorrhagic disease?', '["Erythromycin ointment","Hepatitis B vaccine","Vitamin K (Phytonadione) IM","Ampicillin IV"]'::jsonb, 'Vitamin K (Phytonadione) IM', 'Newborns lack intestinal flora to synthesize Vitamin K; intramuscular Vitamin K prevents Vitamin K deficiency bleeding (VKDB).', 'easy'),
('maternal', 'Using Naegele''s Rule, calculate the estimated date of delivery (EDD) for a pregnant client whose first day of last menstrual period (LMP) was October 10.', '["July 17 of the following year","July 10 of the following year","June 17 of the following year","August 17 of the following year"]'::jsonb, 'July 17 of the following year', 'Naegele''s Rule: Subtract 3 months from LMP (October - 3 = July) and add 7 days (10 + 7 = 17) -> July 17.', 'easy'),
('maternal', 'Which clinical finding indicates Preeclampsia with severe features in a 32-week pregnant client?', '["Blood pressure 138/88 mmHg","Mild dependent ankle edema","Platelet count < 100,000/mcL and severe right upper quadrant pain","Traces of protein in urine"]'::jsonb, 'Platelet count < 100,000/mcL and severe right upper quadrant pain', 'Thrombocytopenia (<100k), epigastric/RUQ pain, renal insufficiency, or BP >= 160/110 qualify as severe features of preeclampsia.', 'hard'),
('maternal', 'A nurse observing a fetal heart rate (FHR) monitor notes late decelerations. What is the cause of late decelerations?', '["Umbilical cord compression","Fetal head compression during contractions","Uteroplacental insufficiency","Maternal fever"]'::jsonb, 'Uteroplacental insufficiency', 'Late decelerations reflect decreased blood flow and oxygen delivery to the fetus during contractions caused by uteroplacental insufficiency.', 'medium'),
('maternal', 'What is the priority nursing action when late decelerations are identified on a fetal monitor tracing?', '["Increase oxytocin (Pitocin) infusion rate","Position client on her left side and apply high-flow oxygen via mask","Perform a digital vaginal examination","Prepare for immediate forceps delivery"]'::jsonb, 'Position client on her left side and apply high-flow oxygen via mask', 'Intrauterine resuscitation for late decelerations: Turn off oxytocin, position client on left side, apply oxygen (8-10 L/min), and increase IV fluids.', 'medium'),
('maternal', 'A postpartum client experiencing heavy vaginal bleeding has a soft, boggy uterus located above the umbilicus. What is the nurse''s FIRST intervention?', '["Administer IV Oxytocin","Perform uterine fundal massage","Insert a Foley catheter","Notify the surgeon immediately"]'::jsonb, 'Perform uterine fundal massage', 'Fundal massage stimulates uterine muscle contraction to compress open sinus vessels and treat uterine atony, the leading cause of postpartum hemorrhage.', 'easy'),
('maternal', 'Which classic symptom differentiates Placenta Previa from Abruptio Placentae?', '["Painless, bright red vaginal bleeding in the third trimester","Painful dark red vaginal bleeding with board-like uterine rigidity","Severe lower abdominal cramping without bleeding","Hyperactive fetal movement"]'::jsonb, 'Painless, bright red vaginal bleeding in the third trimester', 'Placenta previa presents with painless, bright red bleeding. Abruptio placentae presents with painful, dark red bleeding and uterine rigidity.', 'medium'),
('maternal', 'Which antidote must be immediately available at the bedside when a pregnant client receives IV Magnesium Sulfate for preeclampsia?', '["Protamine sulfate","Calcium gluconate","Naloxone","Flumazenil"]'::jsonb, 'Calcium gluconate', 'Calcium gluconate is the specific antidote for magnesium toxicity (loss of deep tendon reflexes, respiratory depression).', 'easy'),
('maternal', 'What stage and phase of labor is a client in when cervical dilation is 8 cm with contractions every 2-3 minutes lasting 70 seconds?', '["First stage, Latent phase","First stage, Active phase","First stage, Transition phase","Second stage"]'::jsonb, 'First stage, Transition phase', 'Transition phase of the first stage of labor is characterized by cervical dilation from 8 to 10 cm with intense, frequent contractions.', 'medium'),
('maternal', 'When should Rh immune globulin (RhOGAM) be administered to an Rh-negative pregnant client to prevent isoimmunization?', '["At 28 weeks gestation and within 72 hours after delivery of an Rh-positive infant","Only after delivery of an Rh-negative infant","At 12 weeks gestation only","To all Rh-positive mothers at delivery"]'::jsonb, 'At 28 weeks gestation and within 72 hours after delivery of an Rh-positive infant', 'RhOGAM prevents maternal antibody formation when an Rh-negative mother carries an Rh-positive fetus.', 'medium'),
('maternal', 'Which screening test is routinely performed for all pregnant clients between 24 and 28 weeks gestation?', '["Group B Streptococcus (GBS) swab","1-hour Oral Glucose Tolerance Test (OGTT)","Alpha-fetoprotein (AFP) screening","Non-stress test (NST)"]'::jsonb, '1-hour Oral Glucose Tolerance Test (OGTT)', 'Universal gestational diabetes screening with a 50g 1-hour glucose challenge test occurs between 24-28 weeks.', 'easy'),
('maternal', 'Which fetal heart rate pattern is considered a benign reassurance requiring no emergency intervention?', '["Variable decelerations","Early decelerations coinciding with contractions","Late decelerations","Sinusoidal baseline pattern"]'::jsonb, 'Early decelerations coinciding with contractions', 'Early decelerations result from fetal head compression during uterine contractions and are benign.', 'easy'),
('maternal', 'What is the primary purpose of administering Betamethasone to a pregnant client at 30 weeks gestation in preterm labor?', '["To stop uterine contractions","To accelerate fetal lung maturity and surfactant production","To prevent maternal infection","To treat gestational hypertension"]'::jsonb, 'To accelerate fetal lung maturity and surfactant production', 'Antenatal corticosteroids (betamethasone) promote fetal surfactant synthesis, reducing neonatal respiratory distress syndrome.', 'medium'),
('maternal', 'Which assessment finding is indicative of positive (diagnostic) sign of pregnancy?', '["Positive home urine pregnancy test","Amenorrhea and morning sickness","Fetal heartbeat detected by Doppler ultrasound","Uterine enlargement"]'::jsonb, 'Fetal heartbeat detected by Doppler ultrasound', 'Positive signs of pregnancy are definitive proof: Fetal heart tones, fetal movement felt by examiner, and visualization by ultrasound.', 'easy'),
('pediatrics', 'A 2-year-old child presents with a barking cough and inspiratory stridor. Which condition does the nurse suspect?', '["Asthma exacerbation","Croup (Laryngotracheobronchitis)","Epiglottitis","Bronchiolitis"]'::jsonb, 'Croup (Laryngotracheobronchitis)', 'Croup is characterized by subglottic airway edema causing a characteristic seal-like barking cough and inspiratory stridor.', 'medium'),
('pediatrics', 'At what age does an infant typically demonstrate the motor milestone of sitting unassisted?', '["2 to 3 months","4 to 5 months","6 to 8 months","10 to 12 months"]'::jsonb, '6 to 8 months', 'Infants typically achieve independent unassisted sitting between 6 and 8 months of age.', 'easy'),
('pediatrics', 'A 4-year-old child presents with high fever, drooling, restlessness, and sitting in a tripod position. Which action is CONTRAINDICATED?', '["Administer humidified oxygen","Inspect the throat using a tongue depressor","Keep the child calm on parent lap","Prepare for emergency endotracheal intubation"]'::jsonb, 'Inspect the throat using a tongue depressor', 'Visual examination of the pharynx with a tongue depressor in suspected Acute Epiglottitis can trigger sudden, fatal laryngospasm.', 'hard'),
('pediatrics', 'Which congenital heart defect causes cyanosis due to right-to-left blood shunting?', '["Ventricular Septal Defect (VSD)","Patent Ductus Arteriosus (PDA)","Tetralogy of Fallot","Coarctation of the Aorta"]'::jsonb, 'Tetralogy of Fallot', 'Tetralogy of Fallot involves 4 defects resulting in right-to-left shunting of unoxygenated blood into systemic circulation.', 'medium'),
('pediatrics', 'A toddler with Tetralogy of Fallot experiences a hypercyanotic ("Tet") spell. What position should the nurse immediately place the toddler in?', '["Knee-to-chest position","High Fowler position","Trendelenburg position","Prone position"]'::jsonb, 'Knee-to-chest position', 'Knee-chest position increases systemic vascular resistance, reducing right-to-left shunting and improving pulmonary blood flow.', 'medium'),
('pediatrics', 'Which dietary enzyme replacement instruction is vital for a pediatric patient diagnosed with Cystic Fibrosis?', '["Take pancreatic enzymes with every meal and snack","Take pancreatic enzymes once daily at bedtime","Dissolve enzymes in hot milk","Skip enzymes if eating high-fat foods"]'::jsonb, 'Take pancreatic enzymes with every meal and snack', 'Pancreatic enzyme replacement therapy must be administered with all meals and snacks to digest fats and proteins.', 'easy'),
('pediatrics', 'At what age is the posterior fontanelle expected to close in a healthy infant?', '["2 to 3 months","6 to 8 months","12 to 18 months","24 months"]'::jsonb, '2 to 3 months', 'The posterior fontanelle closes between 6 and 8 weeks (2-3 months). The anterior fontanelle closes between 12 and 18 months.', 'easy'),
('pediatrics', 'Which symptom is a classic sign of Intussusception in an infant?', '["Currant jelly-like stools containing blood and mucus","Ribbon-like foul-smelling stools","Projectile non-bilious vomiting","Painless rectal bleeding"]'::jsonb, 'Currant jelly-like stools containing blood and mucus', 'Intussusception causes bowel invagination presenting with sudden severe abdominal pain, sausage-shaped abdominal mass, and currant jelly stools.', 'medium'),
('pediatrics', 'What classic sign is noted on physical examination of an infant with Pyloric Stenosis?', '["Sausage-shaped mass in right upper quadrant","Olive-shaped mass in the epigastrium and projectile vomiting","Board-like abdominal rigidity","Scaphoid abdomen"]'::jsonb, 'Olive-shaped mass in the epigastrium and projectile vomiting', 'Hypertrophic pyloric stenosis presents with non-bilious projectile vomiting after feeding and a palpable olive-shaped epigastric mass.', 'medium'),
('pediatrics', 'Which vaccine is routinely administered at birth before discharge from the hospital?', '["Hepatitis B (HepB)","Rotavirus (RV)","DTaP","MMR"]'::jsonb, 'Hepatitis B (HepB)', 'The first dose of Hepatitis B vaccine is recommended for all medically stable newborns within 24 hours of birth.', 'easy'),
('pediatrics', 'A nurse assesses an infant with severe dehydration. Which physical finding is expected?', '["Bulging anterior fontanelle","Depressed/sunken anterior fontanelle and dry mucous membranes","Increased urinary output","Bradypnea"]'::jsonb, 'Depressed/sunken anterior fontanelle and dry mucous membranes', 'Severe dehydration presents with sunken fontanelles, absence of tears, dry membranes, tachycardia, and oliguria.', 'easy'),
('pediatrics', 'Which clinical intervention is contraindicated during acute vaso-occlusive crisis in a child with Sickle Cell Disease?', '["IV hydration","Oxygen therapy for hypoxia","Application of cold compresses to painful joints","Administration of IV opioids for pain"]'::jsonb, 'Application of cold compresses to painful joints', 'Cold applications promote vasoconstriction and sickling. Warm compresses and hydration are indicated.', 'hard'),
('pediatrics', 'Which infant reflex normally disappears by 3 to 4 months of age?', '["Moro (startle) reflex","Babinski reflex","Plantar grasp reflex","Tendon reflexes"]'::jsonb, 'Moro (startle) reflex', 'The Moro reflex fades by 3-4 months. Persistence beyond 6 months indicates neurological abnormality.', 'medium'),
('pediatrics', 'What is the priority assessment for a 6-month-old infant receiving oral digoxin?', '["Assess apical pulse for 1 full minute; hold if HR < 90-110 bpm","Check blood glucose","Measure urine output","Check pupillary reaction"]'::jsonb, 'Assess apical pulse for 1 full minute; hold if HR < 90-110 bpm', 'For infants, digoxin is held if apical heart rate is below 90-110 bpm (compared to <60 bpm in adults).', 'hard'),
('pediatrics', 'A child diagnosed with Kawasaki Disease is at risk for which life-threatening cardiac complication?', '["Coronary artery aneurysms","Ventricular septal defect","Mitral valve prolapse","Coarctation of the aorta"]'::jsonb, 'Coronary artery aneurysms', 'Kawasaki disease causes systemic vasculitis; untreated children are at high risk for coronary artery aneurysms.', 'hard'),
('mentalhealth', 'A patient taking Monoamine Oxidase Inhibitors (MAOIs) must strictly avoid foods containing high levels of which substance?', '["Tyramine","Purines","Gluten","Calcium"]'::jsonb, 'Tyramine', 'Tyramine in aged cheeses, cured meats, and red wine can precipitate a hypertensive crisis when combined with MAOIs.', 'medium'),
('mentalhealth', 'A patient diagnosed with Schizophrenia states, "The radio is sending secret codes directly to my mind." Which response by the nurse demonstrates therapeutic communication?', '["\"That is impossible; radios cannot transmit thoughts.\"","\"I understand that you believe this, but I do not hear any secret codes.\"","\"What are the secret codes telling you to do?\"","\"You should ignore the radio.\""]'::jsonb, '"I understand that you believe this, but I do not hear any secret codes."', 'Therapeutic communication acknowledges the patient''s feelings without validating false beliefs or arguing.', 'medium'),
('mentalhealth', 'Which extrapyramidal side effect (EPS) associated with typical antipsychotics presents with irreversible, involuntary choreoathetoid movements of the tongue and face?', '["Acute dystonia","Akathisia","Tardive dyskinesia","Neuroleptic Malignant Syndrome"]'::jsonb, 'Tardive dyskinesia', 'Tardive dyskinesia is characterized by involuntary facial grimacing and tongue protrusion after prolonged antipsychotic use.', 'hard'),
('mentalhealth', 'What is the priority nursing intervention for a patient exhibiting signs of Neuroleptic Malignant Syndrome (NMS)?', '["Increase the dose of antipsychotic medication","Immediately discontinue the antipsychotic and initiate cooling measures","Administer oral acetaminophen only","Place patient in seclusion"]'::jsonb, 'Immediately discontinue the antipsychotic and initiate cooling measures', 'NMS is a medical emergency (fever, rigidity, autonomic instability). The triggering drug must be stopped immediately.', 'hard'),
('mentalhealth', 'A nurse assesses a patient experiencing severe panic attack. Which intervention should the nurse perform FIRST?', '["Instruct the patient on deep muscle relaxation techniques","Stay with the patient and speak in short, simple sentences","Encourage the patient to analyze the cause of panic","Administer routine oral multivitamins"]'::jsonb, 'Stay with the patient and speak in short, simple sentences', 'During severe panic, cognitive processing is limited. The nurse must provide safety, presence, and clear short directions.', 'easy'),
('mentalhealth', 'Which defense mechanism is demonstrated when a person who was passed over for a promotion states, "I didn''t want that stressful job anyway"?', '["Projection","Rationalization","Sublimation","Displacement"]'::jsonb, 'Rationalization', 'Rationalization involves offering socially acceptable explanations to justify unacceptable thoughts or disappointments.', 'easy'),
('mentalhealth', 'A patient admitted with Major Depressive Disorder expresses hopelessness and states, "Everyone would be better off without me." What is the nurse''s PRIORITY action?', '["Ask directly, \"Are you thinking of ending your life?\"","Leave the patient alone to rest","Notify the hospital chaplain","Reassure the patient that things will get better"]'::jsonb, 'Ask directly, "Are you thinking of ending your life?"', 'Direct assessment of suicidal ideation, intent, and plan is mandatory when suicide clues are expressed.', 'easy'),
('mentalhealth', 'What electrolyte disturbance significantly increases the risk of Lithium toxicity in psychiatric patients?', '["Hyponatremia","Hyperkalemia","Hypercalcemia","Hypomagnesemia"]'::jsonb, 'Hyponatremia', 'Lithium and sodium are processed similarly in renal tubules. Low sodium causes kidneys to reabsorb lithium, raising toxicity risk.', 'medium'),
('mentalhealth', 'Which symptom is early indicator of Alcohol Withdrawal Syndrome typically appearing 6-8 hours after the last drink?', '["Delirium Tremens (DTs)","Tremors, anxiety, diaphoresis, and insomnia","Grand mal seizures","Auditory hallucinations"]'::jsonb, 'Tremors, anxiety, diaphoresis, and insomnia', 'Early alcohol withdrawal (6-8 hours) presents with fine hand tremors, tachycardia, diaphoresis, anxiety, and nausea.', 'easy'),
('mentalhealth', 'Which behavioral intervention is essential when establishing a plan of care for a patient diagnosed with Anorexia Nervosa?', '["Allow unlimited meal times","Observe the patient for 1 hour after meals to prevent purging","Weigh the patient privately once a month","Permit exercise right after eating"]'::jsonb, 'Observe the patient for 1 hour after meals to prevent purging', 'Monitoring patients for at least 60 minutes after meals prevents vomiting or hiding food.', 'medium'),
('mentalhealth', 'Which therapeutic communication technique is being used when the nurse says: "You mentioned feeling overwhelmed. Tell me more about what happened today"?', '["Exploring","Offering false reassurance","Giving advice","Changing the subject"]'::jsonb, 'Exploring', 'Exploring encourages the patient to elaborate on important feelings or events.', 'easy'),
('mentalhealth', 'A patient with Bipolar Disorder in an acute manic phase is disruptive. Which activity is most appropriate for the nurse to plan?', '["Competitive basketball game","Solitary activity like walking with staff or painting","Group trivia competition","Reading a long book in a noisy room"]'::jsonb, 'Solitary activity like walking with staff or painting', 'Patients in acute mania need non-competitive, low-stimulation activities that channel physical energy safely.', 'medium'),
('mentalhealth', 'Which legal standard must be satisfied to execute an involuntary psychiatric commitment?', '["The patient refuses to take prescribed oral medications","The patient poses an immediate danger to self or others, or is gravely disabled","The family demands hospitalization","The patient missed outpatient therapy"]'::jsonb, 'The patient poses an immediate danger to self or others, or is gravely disabled', 'Involuntary admission requires legal criteria proving danger to self/others or inability to meet basic survival needs.', 'medium'),
('mentalhealth', 'What is the primary goal of cognitive-behavioral therapy (CBT)?', '["Uncover repressed childhood memories","Identify and reframe negative automatic thoughts and maladaptive behaviors","Prescribe psychotropic medications","Analyze dream symbolism"]'::jsonb, 'Identify and reframe negative automatic thoughts and maladaptive behaviors', 'CBT focuses on altering dysfunctional thought patterns and behaviors to improve emotional regulation.', 'easy'),
('mentalhealth', 'Which medication class is considered first-line pharmacological treatment for Generalized Anxiety Disorder and Depression?', '["Selective Serotonin Reuptake Inhibitors (SSRIs)","Barbiturates","Typical Antipsychotics","Monoamine Oxidase Inhibitors"]'::jsonb, 'Selective Serotonin Reuptake Inhibitors (SSRIs)', 'SSRIs (e.g., Sertraline, Escitalopram) are first-line for chronic anxiety and depressive disorders due to safety profile.', 'easy'),
('fluids', 'A nurse reviews Arterial Blood Gas (ABG) results: pH 7.28, PaCO2 55 mmHg, HCO3- 24 mEq/L. How should the nurse interpret these findings?', '["Uncompensated Respiratory Acidosis","Uncompensated Metabolic Acidosis","Compensated Respiratory Alkalosis","Fully Compensated Metabolic Alkalosis"]'::jsonb, 'Uncompensated Respiratory Acidosis', 'pH < 7.35 (Acidemia), PaCO2 > 45 (Respiratory etiology), HCO3- normal (Uncompensated).', 'hard'),
('fluids', 'Which IV fluid is considered hypertonic and used to treat severe hyponatremia under close monitoring?', '["0.45% Normal Saline","0.9% Normal Saline","3% Sodium Chloride","Lactated Ringer solution"]'::jsonb, '3% Sodium Chloride', '3% NaCl is a hypertonic saline solution used in emergency settings to treat critical, symptomatic hyponatremia.', 'medium'),
('fluids', 'A patient ABG reads: pH 7.49, PaCO2 38 mmHg, HCO3- 30 mEq/L. Which condition matches this ABG profile?', '["Metabolic Alkalosis","Respiratory Acidosis","Metabolic Acidosis","Respiratory Alkalosis"]'::jsonb, 'Metabolic Alkalosis', 'pH > 7.45 (Alkalemia) with high HCO3- (>26 mEq/L) indicates metabolic alkalosis (e.g., from severe vomiting or gastric suctioning).', 'medium'),
('fluids', 'Which ECG abnormality is classic indicator of severe Hyperkalemia?', '["Tall peaked T waves and widened QRS complex","ST segment depression and prominent U waves","Prolonged QT interval","Inverted P waves"]'::jsonb, 'Tall peaked T waves and widened QRS complex', 'Hyperkalemia causes narrow tall peaked T waves initially, followed by PR prolongation and widened QRS complexes.', 'medium'),
('fluids', 'Which ECG abnormality is classic indicator of Hypokalemia?', '["Prominent U waves and ST segment depression","Tall peaked T waves","Shortened QT interval","Pathological Q waves"]'::jsonb, 'Prominent U waves and ST segment depression', 'Hypokalemia causes flat T waves, ST depression, and appearance of U waves on ECG.', 'medium'),
('fluids', 'Which IV fluid solution is isotonic and used for blood transfusion tubing priming?', '["0.9% Normal Saline (0.9% NaCl)","5% Dextrose in Water (D5W)","Lactated Ringer solution","0.45% Sodium Chloride"]'::jsonb, '0.9% Normal Saline (0.9% NaCl)', 'Only 0.9% Normal Saline is compatible with blood products; dextrose solutions cause hemolysis.', 'easy'),
('fluids', 'What is the primary physiological risk of correcting severe hyponatremia too rapidly with hypertonic saline?', '["Osmotic Demyelination Syndrome (Central Pontine Myelinolysis)","Cerebral edema","Acute pulmonary embolism","Renal papillary necrosis"]'::jsonb, 'Osmotic Demyelination Syndrome (Central Pontine Myelinolysis)', 'Rapid correction of hyponatremia (>10-12 mEq/L in 24 hrs) causes brain cell dehydration and catastrophic central pontine myelinolysis.', 'hard'),
('fluids', 'A patient with persistent severe diarrhea is at highest risk for which acid-base disturbance?', '["Metabolic Acidosis","Metabolic Alkalosis","Respiratory Acidosis","Respiratory Alkalosis"]'::jsonb, 'Metabolic Acidosis', 'Diarrheal fluid contains large quantities of bicarbonate; excessive loss leads to metabolic acidosis.', 'medium'),
('fluids', 'A patient with severe nasogastric suctioning is at highest risk for which acid-base disturbance?', '["Metabolic Alkalosis","Metabolic Acidosis","Respiratory Acidosis","Respiratory Alkalosis"]'::jsonb, 'Metabolic Alkalosis', 'Gastric secretions contain high concentrations of hydrochloric acid (HCl); suctioning removes acid causing metabolic alkalosis.', 'easy'),
('fluids', 'What is the normal therapeutic range for adult serum sodium levels?', '["135 to 145 mEq/L","120 to 130 mEq/L","148 to 158 mEq/L","110 to 125 mEq/L"]'::jsonb, '135 to 145 mEq/L', 'Normal serum sodium concentration is 135-145 mEq/L.', 'easy'),
('fluids', 'What is the normal therapeutic range for adult serum potassium levels?', '["3.5 to 5.0 mEq/L","1.5 to 2.5 mEq/L","5.5 to 7.0 mEq/L","8.0 to 10.0 mEq/L"]'::jsonb, '3.5 to 5.0 mEq/L', 'Normal serum potassium concentration is 3.5-5.0 mEq/L.', 'easy'),
('fluids', 'Which fluid compartment contains approximately two-thirds of total body water?', '["Intracellular fluid (ICF)","Extracellular fluid (ECF)","Intravascular plasma","Interstitial fluid"]'::jsonb, 'Intracellular fluid (ICF)', 'Intracellular fluid accounts for ~60-65% (two-thirds) of total body water.', 'easy'),
('fluids', 'A nurse administers IV Potassium Chloride piggyback. What is the maximum safe peripheral infusion rate?', '["10 mEq/hour","40 mEq/hour","100 mEq/hour","IV push over 1 minute"]'::jsonb, '10 mEq/hour', 'Potassium MUST NEVER be given IV push. Maximum peripheral IV infusion rate is 10 mEq/hr to prevent cardiac arrest and phlebitis.', 'hard'),
('fluids', 'Which clinical sign is characteristic of Hypercalcemia?', '["Decreased deep tendon reflexes and muscle weakness","Trousseau sign and Chvostek sign","Hyperactive reflexes and tetany","Positive Babinski sign"]'::jsonb, 'Decreased deep tendon reflexes and muscle weakness', 'Hypercalcemia depresses neuromuscular excitability, causing muscle weakness, hyporeflexia, and constipation ("groans, stones, bones").', 'medium'),
('fluids', 'An ABG shows: pH 7.31, PaCO2 30 mmHg, HCO3- 16 mEq/L. What is the acid-base diagnosis?', '["Partially Compensated Metabolic Acidosis","Uncompensated Respiratory Acidosis","Fully Compensated Respiratory Alkalosis","Metabolic Alkalosis"]'::jsonb, 'Partially Compensated Metabolic Acidosis', 'pH low (Acidosis), HCO3- low (Metabolic primary), PaCO2 low (Compensatory hyperventilation attempting to raise pH).', 'hard'),
('anatomy', 'Which chamber of the human heart receives oxygenated blood directly from the pulmonary veins?', '["Right Atrium","Right Ventricle","Left Atrium","Left Ventricle"]'::jsonb, 'Left Atrium', 'Oxygenated blood from pulmonary circulation enters the Left Atrium via four pulmonary veins.', 'easy'),
('anatomy', 'Which cranial nerve is tested when asking a patient to stick out their tongue and move it side to side?', '["Cranial Nerve IX (Glossopharyngeal)","Cranial Nerve X (Vagus)","Cranial Nerve XI (Accessory)","Cranial Nerve XII (Hypoglossal)"]'::jsonb, 'Cranial Nerve XII (Hypoglossal)', 'CN XII (Hypoglossal nerve) controls tongue muscle movement and lingual motor function.', 'easy'),
('anatomy', 'Which functional unit of the kidney is responsible for blood filtration and urine formation?', '["Glomerulus","Nephron","Renal pelvis","Calyx"]'::jsonb, 'Nephron', 'The nephron is the structural and functional microscopic unit of the kidney.', 'easy'),
('anatomy', 'Which endocrine gland secretes Parathyroid Hormone (PTH) to regulate serum calcium levels?', '["Thyroid gland","Parathyroid glands","Adrenal cortex","Pituitary gland"]'::jsonb, 'Parathyroid glands', 'Four small parathyroid glands posterior to the thyroid secrete PTH to elevate calcium levels.', 'easy'),
('anatomy', 'Where is the pacemaker (SA node) of the heart anatomical located?', '["Wall of the right atrium near superior vena cava","Interventricular septum","Left ventricle apex","Atrioventricular junction"]'::jsonb, 'Wall of the right atrium near superior vena cava', 'The Sinoatrial (SA) node is located in the upper posterior wall of the right atrium.', 'medium'),
('anatomy', 'Which valve prevents backflow of blood from the left ventricle into the left atrium during systole?', '["Tricuspid valve","Mitral (Bicuspid) valve","Aortic semilunar valve","Pulmonary semilunar valve"]'::jsonb, 'Mitral (Bicuspid) valve', 'The Mitral (bicuspid) valve separates left atrium and left ventricle.', 'easy'),
('anatomy', 'Which section of the brain controls vital autonomic functions such as heart rate, blood pressure, and respiration?', '["Cerebellum","Medulla Oblongata","Frontal Lobe","Occipital Lobe"]'::jsonb, 'Medulla Oblongata', 'The medulla oblongata in the brainstem houses cardiorespiratory control centers.', 'medium'),
('anatomy', 'Which artery is primarily palpated to assess pulse during adult cardiopulmonary resuscitation (CPR)?', '["Radial artery","Carotid artery","Brachial artery","Dorsalis pedis artery"]'::jsonb, 'Carotid artery', 'The carotid artery is the central pulse recommended for adult cardiac arrest pulse checks.', 'easy'),
('anatomy', 'Which blood vessel carries deoxygenated blood from the heart to the lungs?', '["Pulmonary vein","Pulmonary artery","Aorta","Superior vena cava"]'::jsonb, 'Pulmonary artery', 'The pulmonary trunk and pulmonary arteries carry deoxygenated blood from right ventricle to lungs.', 'easy'),
('anatomy', 'Which organ produces bile for fat emulsification?', '["Gallbladder","Liver","Pancreas","Duodenum"]'::jsonb, 'Liver', 'Bile is synthesized by hepatocytes in the liver and stored/concentrated in the gallbladder.', 'easy'),
('anatomy', 'Which lobe of the cerebral cortex is primarily responsible for processing visual information?', '["Frontal Lobe","Temporal Lobe","Occipital Lobe","Parietal Lobe"]'::jsonb, 'Occipital Lobe', 'The occipital lobe contains the primary visual cortex.', 'easy'),
('anatomy', 'Which bone is the longest and strongest bone in the human body?', '["Tibia","Femur","Humerus","Fibula"]'::jsonb, 'Femur', 'The femur (thigh bone) is the longest and strongest human bone.', 'easy'),
('anatomy', 'Which hormone is produced by the beta cells of the Islets of Langerhans in the pancreas?', '["Glucagon","Insulin","Somatostatin","Cortisol"]'::jsonb, 'Insulin', 'Beta cells secrete insulin; alpha cells secrete glucagon.', 'medium'),
('anatomy', 'What is the primary site of nutrient absorption in the gastrointestinal tract?', '["Stomach","Small Intestine (Jejunum & Ileum)","Large Intestine","Esophagus"]'::jsonb, 'Small Intestine (Jejunum & Ileum)', 'The mucosal plicae and villi of the small intestine absorb over 90% of nutrients.', 'easy'),
('anatomy', 'Which layer of the heart wall is composed of cardiac muscle fibers responsible for pumping blood?', '["Endocardium","Myocardium","Epicardium","Pericardium"]'::jsonb, 'Myocardium', 'The myocardium is the thick muscular middle layer of the heart wall.', 'easy');
